std::atomic<int> atm_i(10);
int expected = 10;
const int desired = 20;

// Signature: (&expected, desired, mo_success, mo_failure)
// Constraint: mo_success >= mo_failure

atm_i.compare_exchange_strong_explicit(
    expected,
    desired,
    std::memory_order_release, // Success: Writes desired value
    std::memory_order_relaxed  // Failure: Only loads current value
);

// RMW Spin Loop Example
int current = atm_i.load();
do {
    // expected is updated with current value on failure
    expected = current;
} while (!atm_i.compare_exchange_strong_explicit(
    expected,
    expected + 1,
    std::memory_order_acq_rel,
    std::memory_order_acquire
));
